#include <iostream>
int main() {
    int count{};
    long long sum{};
    bool stopped{};
    while (!stopped) {
        std::cin >> std::ws;
        if (std::cin.eof()) { break; }
        int value{};
        if (!(std::cin >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        if (value == 0) { stopped = true; }
        else {
            if (count == 100) { std::cout << "invalid\n"; return 0; }
            ++count;
            sum += value;
        }
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
    std::cout << count << ' ' << sum << '\n';
}

