#include <iostream>
#include <sstream>
#include <string>

bool parseValue(const std::string& token, int& value) {
    std::istringstream input{token};
    if (!(input >> value) || value < -1000 || value > 1000) {
        return false;
    }
    input >> std::ws;
    return input.eof();
}

int main() {
    int count{};
    int sum{};
    std::string token;
    while (std::cin >> token) {
        int value{};
        if (!parseValue(token, value)) {
            std::cout << "invalid\n";
            return 0;
        }
        // TODO: handle the zero marker, check the count limit and update
        // the state. Verify the rest of the input if you stop at a marker.
    }
    std::cout << count << ' ' << sum << '\n';
}
